    // 1. Copy: gmem → smem
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();

    // 2. Compute: smem → register → accumulate
    gemm(tCsA, tCsB, tCrC);

    __syncthreads();
